<script setup lang="ts">
/**
 * A short text hint shown on hover or focus (`design/components/tooltip.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tooltip.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onMounted, useId, useTemplateRef, watch } from 'vue'

import * as zag from '@zag-js/tooltip'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  TOOLTIP_DELAY_MS,
  TOOLTIP_SKIP_DELAY_MS,
  anchorProps,
  syncTriggerAnchor,
  useDirection,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/overlays/tooltip.module.css'

export type TooltipAlign = NonNullable<TooltipProps['align']>

export type TooltipSide = NonNullable<TooltipProps['side']>

export interface TooltipProps {
  align?: 'start' | 'center' | 'end'
  content: string
  /**
   * Opens on mount, for galleries and tests.
   */
  defaultOpen?: boolean
  side?: 'bottom' | 'top' | 'right' | 'left'
}

defineOptions({ name: 'Tooltip', inheritAttrs: false })

const props = withDefaults(defineProps<TooltipProps>(), {
  align: 'center',
  defaultOpen: undefined,
  side: 'top',
})
defineSlots<{ default: (props: Record<string, never>) => unknown }>()
const uid = useId()
const anchor = useTemplateRef<HTMLElement>('anchor')
const bubble = useTemplateRef<HTMLElement>('bubble')
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    defaultOpen: props.defaultOpen,
    openDelay: TOOLTIP_DELAY_MS,
    closeDelay: TOOLTIP_SKIP_DELAY_MS,
    positioning: {
      placement: props.align === 'center' ? props.side : `${props.side}-${props.align}`,
      gutter: 0,
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const present = usePresence(() => api.value.open, bubble, 'tooltip.bubble', {
  get side() {
    return props.side
  },
  get align() {
    return props.align
  },
})
const effect1 = () => {
  syncTriggerAnchor(anchor.value, api.value.getTriggerProps(), api.value.open, false)
}
onMounted(effect1)
watch(() => api.value.open, effect1, { flush: 'post' })
</script>

<template>
  <span
    ref="anchor"
    v-bind="anchorProps(api.getTriggerProps())"
    :class="styles.anchor"
    data-tooltip-part="trigger"
  >
    <slot />
  </span>
  <Teleport to="body">
    <div v-if="present" v-bind="api.getPositionerProps()">
      <!-- bubble -->
      <div
        ref="bubble"
        v-bind="api.getContentProps()"
        :class="styles.bubble"
        :style="{ '--radix-tooltip-content-available-width': 'var(--available-width)' }"
        :hidden="undefined"
        :data-state="api.open ? 'delayed-open' : 'closed'"
        data-member="tooltip"
      >
        {{ content }}
      </div>
    </div>
  </Teleport>
</template>
